    path: "compose.yml",
    mode: 0o644,
    content: "# selfhost on one server: Postgres, the OpenTelemetry collector and the selfhost API.\n# Copy .env.example to .env and fill it in, then run `docker compose up -d`. See README.md.\n# compose.tls.yml adds HTTPS with Caddy and compose.signin.yml adds console sign-in.\n# Third-party images are pinned to exact versions; a test fails on `latest` or a missing tag.\nname: selfhost\n\nx-logging: &logging\n  driver: json-file\n  options:\n    max-size: 10m\n    max-file: \"5\"\n\nservices:\n  postgres:\n    image: postgres:16.15\n    restart: unless-stopped\n    environment:\n      POSTGRES_DB: ${POSTGRES_DB:-selfhost}\n      POSTGRES_USER: ${POSTGRES_USER:-selfhost}\n      POSTGRES_PASSWORD: ${POSTGRES_PASSWORD:?Set POSTGRES_PASSWORD in .env}\n    volumes:\n      - postgres-data:/var/lib/postgresql/data\n    healthcheck:\n      test: [\"CMD-SHELL\", 'pg_isready -U \"$$POSTGRES_USER\" -d \"$$POSTGRES_DB\"']\n      interval: 5s\n      timeout: 5s\n      retries: 10\n      start_period: 10s\n    logging: *logging\n\n  selfhost:\n    # Pulls the release named by SELFHOST_VERSION, or builds it from this checkout when the\n    # image is not published or with `docker compose up -d --build`.\n    image: ${SELFHOST_IMAGE:-ghcr.io/getselfhostai/selfhost}:${SELFHOST_VERSION:?Set SELFHOST_VERSION in .env}\n    build:\n      context: ../..\n      dockerfile: deploy/docker/Dockerfile\n    restart: unless-stopped\n    depends_on:\n      postgres:\n        condition: service_healthy\n    environment:\n      # Migrations run on start, under a lock, before the server listens.\n      DATABASE_URL: postgres://${POSTGRES_USER:-selfhost}:${POSTGRES_PASSWORD}@postgres:5432/${POSTGRES_DB:-selfhost}\n      SELFHOST_TOKEN: ${SELFHOST_TOKEN:?Set SELFHOST_TOKEN in .env}\n      SELFHOST_RETENTION_SWEEP: ${SELFHOST_RETENTION_SWEEP:-daily}\n      # The URL people reach the server at, for links the server writes (brief traces).\n      SELFHOST_PUBLIC_URL: ${SELFHOST_PUBLIC_URL:-}\n      # GitHub App, optional: POST /v1/github/webhooks answers 404 until the first three are set.\n      SELFHOST_GITHUB_APP_ID: ${SELFHOST_GITHUB_APP_ID:-}\n      SELFHOST_GITHUB_PRIVATE_KEY: ${SELFHOST_GITHUB_PRIVATE_KEY:-}\n      SELFHOST_GITHUB_WEBHOOK_SECRET: ${SELFHOST_GITHUB_WEBHOOK_SECRET:-}\n      SELFHOST_GITHUB_TEAM: ${SELFHOST_GITHUB_TEAM:-}\n      # Issuer of the CI tokens proof receipts are posted with; set only on GitHub Enterprise Server.\n      SELFHOST_GITHUB_OIDC_ISSUER: ${SELFHOST_GITHUB_OIDC_ISSUER:-https://token.actions.githubusercontent.com}\n      # A LiteLLM proxy the team already runs, optional (compose.gateway.yml sets the bundled\n      # Bifrost instead). The admin key is LiteLLM's master key.\n      SELFHOST_GATEWAY_TOOL: ${SELFHOST_GATEWAY_TOOL:-}\n      SELFHOST_GATEWAY_URL: ${SELFHOST_GATEWAY_URL:-}\n      SELFHOST_GATEWAY_PUBLIC_URL: ${SELFHOST_GATEWAY_PUBLIC_URL:-}\n      SELFHOST_GATEWAY_ADMIN_KEY: ${SELFHOST_GATEWAY_ADMIN_KEY:-}\n      # An Apprise API server the team already runs (compose.notify.yml sets its own).\n      SELFHOST_APPRISE_URL: ${SELFHOST_APPRISE_URL:-}\n    ports:\n      - \"${SELFHOST_BIND:-127.0.0.1}:${SELFHOST_PORT:-4400}:4400\"\n    # Health check: HEALTHCHECK in the image, GET /v1/health.\n    logging: *logging\n\n  # The collector image has no shell or HTTP client, so its health check runs a static busybox\n  # that this one-shot service copies into a shared volume. The rename keeps a copy made during a\n  # running health check from failing on a busy file.\n  collector-probe:\n    image: busybox:1.37.0-musl\n    command:\n      - sh\n      - -c\n      - cp /bin/busybox /probe/busybox.new && mv -f /probe/busybox.new /probe/busybox\n    volumes:\n      - collector-probe:/probe\n    logging: *logging\n\n  otel-collector:\n    image: otel/opentelemetry-collector-contrib:0.164.0\n    restart: unless-stopped\n    depends_on:\n      collector-probe:\n        condition: service_completed_successfully\n      selfhost:\n        condition: service_healthy\n    environment:\n      SELFHOST_TOKEN: ${SELFHOST_TOKEN:?Set SELFHOST_TOKEN in .env}\n      SELFHOST_OTLP_TOKEN: ${SELFHOST_OTLP_TOKEN:?Set SELFHOST_OTLP_TOKEN in .env}\n    volumes:\n      - ./otel-collector.yaml:/etc/otelcol-contrib/config.yaml:ro\n      - collector-probe:/probe:ro\n    ports:\n      - \"${OTLP_BIND:-127.0.0.1}:${OTLP_GRPC_PORT:-4317}:4317\"\n      - \"${OTLP_BIND:-127.0.0.1}:${OTLP_HTTP_PORT:-4318}:4318\"\n    healthcheck:\n      test:\n        - CMD\n        - /probe/busybox\n        - wget\n        - -q\n        - -T\n        - \"4\"\n        - -O\n        - /dev/null\n        - http://127.0.0.1:13133/\n      interval: 10s\n      timeout: 5s\n      retries: 5\n      start_period: 10s\n    logging: *logging\n\nvolumes:\n  postgres-data:\n  collector-probe:\n",
