    path: "compose.signin.yml",
    mode: 0o644,
    content: "# GitHub or Google sign-in for the console: oauth2-proxy checks the login before Caddy serves\n# anything outside /v1 and /otlp, which keep their bearer tokens so CLIs, hooks and agents work\n# as before. A signed-in browser reads /v1 as the person whose email it signed in with, which\n# must be their person id on the server (selfhost team invite --email). Use it with\n# compose.tls.yml:\n#   COMPOSE_FILE=compose.yml:compose.tls.yml:compose.signin.yml\n# The OAuth app's callback URL is https://<SELFHOST_DOMAIN>/oauth2/callback.\nservices:\n  oauth2-proxy:\n    image: quay.io/oauth2-proxy/oauth2-proxy:v7.15.6\n    restart: unless-stopped\n    environment:\n      OAUTH2_PROXY_PROVIDER: ${SELFHOST_SIGNIN_PROVIDER:?Set SELFHOST_SIGNIN_PROVIDER to github or google in .env}\n      OAUTH2_PROXY_CLIENT_ID: ${SELFHOST_SIGNIN_CLIENT_ID:?Set SELFHOST_SIGNIN_CLIENT_ID in .env}\n      OAUTH2_PROXY_CLIENT_SECRET: ${SELFHOST_SIGNIN_CLIENT_SECRET:?Set SELFHOST_SIGNIN_CLIENT_SECRET in .env}\n      OAUTH2_PROXY_COOKIE_SECRET: ${SELFHOST_SIGNIN_COOKIE_SECRET:?Set SELFHOST_SIGNIN_COOKIE_SECRET in .env}\n      OAUTH2_PROXY_REDIRECT_URL: https://${SELFHOST_DOMAIN:?Set SELFHOST_DOMAIN in .env}/oauth2/callback\n      OAUTH2_PROXY_WHITELIST_DOMAINS: ${SELFHOST_DOMAIN}\n      # Who may sign in: an email in one of these domains (comma separated) or listed in\n      # signin-emails.txt, one per line. With SELFHOST_SIGNIN_GITHUB_ORG set, they must also be\n      # in that GitHub organization.\n      OAUTH2_PROXY_EMAIL_DOMAINS: ${SELFHOST_SIGNIN_EMAIL_DOMAINS:-}\n      OAUTH2_PROXY_AUTHENTICATED_EMAILS_FILE: /etc/oauth2-proxy/emails.txt\n      OAUTH2_PROXY_GITHUB_ORG: ${SELFHOST_SIGNIN_GITHUB_ORG:-}\n      OAUTH2_PROXY_HTTP_ADDRESS: 0.0.0.0:4180\n      OAUTH2_PROXY_REVERSE_PROXY: \"true\"\n      # Caddy asks /oauth2/auth before serving the console, so oauth2-proxy proxies nothing.\n      OAUTH2_PROXY_UPSTREAMS: static://202\n      OAUTH2_PROXY_SKIP_PROVIDER_BUTTON: \"true\"\n      # /oauth2/auth answers with X-Auth-Request-Email, which Caddy passes to selfhost.\n      OAUTH2_PROXY_SET_XAUTHREQUEST: \"true\"\n    volumes:\n      - ./signin-emails.txt:/etc/oauth2-proxy/emails.txt:ro\n    logging:\n      driver: json-file\n      options:\n        max-size: 10m\n        max-file: \"5\"\n\n  caddy:\n    environment:\n      SELFHOST_CONSOLE_ACCESS: signin\n      SELFHOST_SIGNIN_PROXY_SECRET: ${SELFHOST_SIGNIN_PROXY_SECRET:?Set SELFHOST_SIGNIN_PROXY_SECRET in .env}\n\n  # The server believes the email Caddy forwards only with this secret, so a request that\n  # reaches port 4400 some other way signs in as nobody.\n  selfhost:\n    environment:\n      SELFHOST_SIGNIN_PROXY_SECRET: ${SELFHOST_SIGNIN_PROXY_SECRET:?Set SELFHOST_SIGNIN_PROXY_SECRET in .env}\n      # The org sign-in is for when an email is in teams of several orgs (default: its first).\n      SELFHOST_SIGNIN_ORG: ${SELFHOST_SIGNIN_ORG:-}\n",
