    path: "compose.gateway.yml",
    mode: 0o644,
    content: "# The AI gateway: Bifrost (github.com/maximhq/bifrost, Apache 2.0) next to the server. It holds\n# the provider keys and answers agents at https://<SELFHOST_DOMAIN>/llm/ through Caddy, only with\n# a virtual key selfhost issued (selfhost gateway connect). Its keys, budgets and request logs\n# live in a database of their own on the same Postgres. The selfhost server writes teams, keys\n# and budgets to it from selfhost.toml and reads its request logs into the ledger.\n# Use it with compose.tls.yml:\n#   COMPOSE_FILE=compose.yml:compose.tls.yml:compose.gateway.yml\n# Provider keys go in .env (ANTHROPIC_API_KEY and the others in .env.example); install.sh writes\n# bifrost.json, which names only the providers whose keys are set, then starts it.\nservices:\n  # Creates the bifrost database once; does nothing when it exists.\n  gateway-db:\n    image: postgres:16.15\n    depends_on:\n      postgres:\n        condition: service_healthy\n    environment:\n      PGHOST: postgres\n      PGUSER: ${POSTGRES_USER:-selfhost}\n      PGPASSWORD: ${POSTGRES_PASSWORD:?Set POSTGRES_PASSWORD in .env}\n      PGDATABASE: ${POSTGRES_DB:-selfhost}\n    command:\n      - sh\n      - -c\n      - >-\n        psql -tAc \"SELECT 1 FROM pg_database WHERE datname = 'bifrost'\" | grep -q 1 ||\n        psql -c \"CREATE DATABASE bifrost\"\n    logging:\n      driver: json-file\n      options:\n        max-size: 10m\n        max-file: \"5\"\n\n  bifrost:\n    image: maximhq/bifrost:v2.4.0\n    restart: unless-stopped\n    depends_on:\n      gateway-db:\n        condition: service_completed_successfully\n    environment:\n      APP_PORT: \"8080\"\n      APP_HOST: 0.0.0.0\n      LOG_LEVEL: info\n      LOG_STYLE: json\n      # Read by bifrost.json as env.<NAME>; nothing secret is written in that file.\n      SELFHOST_GATEWAY_ADMIN_KEY: ${SELFHOST_GATEWAY_ADMIN_KEY:?Set SELFHOST_GATEWAY_ADMIN_KEY in .env}\n      SELFHOST_GATEWAY_ENCRYPTION_KEY: ${SELFHOST_GATEWAY_ENCRYPTION_KEY:?Set SELFHOST_GATEWAY_ENCRYPTION_KEY in .env}\n      BIFROST_DB_USER: ${POSTGRES_USER:-selfhost}\n      BIFROST_DB_PASSWORD: ${POSTGRES_PASSWORD:?Set POSTGRES_PASSWORD in .env}\n      # Provider keys stay in this container: the selfhost server never sees them.\n      ANTHROPIC_API_KEY: ${ANTHROPIC_API_KEY:-}\n      OPENAI_API_KEY: ${OPENAI_API_KEY:-}\n      FIREWORKS_API_KEY: ${FIREWORKS_API_KEY:-}\n      AWS_ACCESS_KEY_ID: ${AWS_ACCESS_KEY_ID:-}\n      AWS_SECRET_ACCESS_KEY: ${AWS_SECRET_ACCESS_KEY:-}\n      AZURE_API_KEY: ${AZURE_API_KEY:-}\n      AZURE_ENDPOINT: ${AZURE_ENDPOINT:-}\n      VERTEX_PROJECT_ID: ${VERTEX_PROJECT_ID:-}\n      VERTEX_CREDENTIALS: ${VERTEX_CREDENTIALS:-}\n    volumes:\n      # The app directory; with Postgres for both stores it holds only Bifrost's own scratch files.\n      - bifrost-data:/app/data\n      - ./bifrost.json:/app/data/config.json:ro\n    # For Bifrost's own web UI over an SSH tunnel (ssh -L 8080:127.0.0.1:8080), never the internet.\n    ports:\n      - \"${GATEWAY_BIND:-127.0.0.1}:${GATEWAY_PORT:-8080}:8080\"\n    # Health check: HEALTHCHECK in the image, GET /health.\n    logging:\n      driver: json-file\n      options:\n        max-size: 10m\n        max-file: \"5\"\n\n  selfhost:\n    environment:\n      SELFHOST_GATEWAY_TOOL: bifrost\n      SELFHOST_GATEWAY_URL: http://bifrost:8080\n      SELFHOST_GATEWAY_ADMIN_KEY: ${SELFHOST_GATEWAY_ADMIN_KEY:?Set SELFHOST_GATEWAY_ADMIN_KEY in .env}\n\n  # Caddy sends /llm/ to Bifrost. It does not wait for Bifrost, so the API and the console come\n  # up even when the gateway does not.\n  caddy:\n    environment:\n      SELFHOST_GATEWAY: \"on\"\n\nvolumes:\n  bifrost-data:\n",
