    path: "compose.notify.yml",
    mode: 0o644,
    content: "# Notifications: the Apprise API server (github.com/caronc/apprise-api, BSD-2) next to the\n# selfhost server. selfhost decides what to send and when; Apprise delivers it to Telegram,\n# Slack, email, Teams, Discord, ntfy and 100+ other services. Only the server reaches it, on the\n# compose network: no port is published, and it keeps no configuration of its own (stateless\n# /notify only), so the target URLs, which hold secrets, stay in selfhost's database.\n# Add it to COMPOSE_FILE:\n#   COMPOSE_FILE=compose.yml:compose.tls.yml:compose.notify.yml\n# A team that already runs Apprise leaves this file out and sets SELFHOST_APPRISE_URL in .env.\nservices:\n  apprise:\n    image: caronc/apprise:2.0.2\n    restart: unless-stopped\n    environment:\n      APPRISE_STATEFUL_MODE: disabled\n      APPRISE_ATTACH_SIZE: \"0\"\n      APPRISE_WORKER_COUNT: \"1\"\n    logging:\n      driver: json-file\n      options:\n        max-size: 10m\n        max-file: \"5\"\n\n  selfhost:\n    depends_on:\n      apprise:\n        condition: service_started\n    environment:\n      SELFHOST_APPRISE_URL: http://apprise:8000\n",
